/**
 * UT Book Auto-Scanner Content Script
 * Tailored for Kotobee Reader on univterbuka.kotobee.com
 * by Adjie Kurniawan
 */

(() => {
  if (window.__UT_SCANNER_INITIALIZED__) return;
  window.__UT_SCANNER_INITIALIZED__ = true;

  // Scanner state (kept in-memory for lightning-fast performance without storage lagging)
  let state = {
    isScanning: false,
    delaySeconds: 2.5,
    maxPages: 15, // 0 = unlimited, 5, 10, 15, 25, 50
    scanMode: 'screenshot',
    bookTitle: '',
    pages: [], // [{ pageNum, title, image, width, height, timestamp, hash }]
    lastContentHash: '',
    consecutiveSameCount: 0,
    timerId: null
  };

  // Automatically unblock copy, cut, contextmenu, and text selection
  function unblockProtection() {
    try {
      const unlockCss = `
        * {
          -webkit-user-select: text !important;
          -moz-user-select: text !important;
          -ms-user-select: text !important;
          user-select: text !important;
        }
      `;
      const style = document.createElement('style');
      style.id = 'ut-unblock-styles';
      style.textContent = unlockCss;
      document.documentElement.appendChild(style);

      document.querySelectorAll('iframe').forEach(iframe => {
        try {
          const idoc = iframe.contentDocument || iframe.contentWindow?.document;
          if (idoc && !idoc.getElementById('ut-unblock-styles')) {
            const istyle = idoc.createElement('style');
            istyle.id = 'ut-unblock-styles';
            istyle.textContent = unlockCss;
            idoc.documentElement?.appendChild(istyle);
          }
        } catch (e) {}
      });

      const events = ['copy', 'cut', 'selectstart', 'contextmenu'];
      events.forEach(eventName => {
        window.addEventListener(eventName, (e) => {
          e.stopImmediatePropagation();
        }, true);
      });
    } catch (e) {}
  }

  // Inject UI Widget
  function injectWidget() {
    if (document.getElementById('ut-scanner-widget')) return;

    const logoSrc = "data:image/png;base64,";

    const widget = document.createElement('div');
    widget.id = 'ut-scanner-widget';
    widget.innerHTML = `
      <div class="ut-widget-header" id="ut-widget-drag-handle" title="Klik tahan dan geser untuk memindahkan posisi">
        <div class="ut-widget-title-wrap">
          <div class="ut-widget-icon">
            ${logoSrc ? `<img src="${logoSrc}" class="ut-widget-logo-img" alt="Logo">` : '📖'}
          </div>
          <div class="ut-widget-text-group">
            <div class="ut-widget-title">UT Book Scanner <span style="font-size: 10px; opacity: 0.85; font-weight: 500;">v1.0.0</span></div>
            <div style="font-size: 10px; opacity: 0.85; font-weight: 400;">by Adjie Kurniawan</div>
          </div>
        </div>
        <div class="ut-widget-controls">
          <button class="ut-btn-icon" id="ut-btn-minimize" title="Minimize / Perbesar" aria-label="Minimize">− </button>
        </div>
      </div>
      <div class="ut-widget-body">
        <div class="ut-status-card">
          <div class="ut-status-row">
            <span class="ut-status-label">Status:</span>
            <span class="ut-status-badge idle" id="ut-badge-status">IDLE</span>
          </div>
          <div class="ut-status-row">
            <span class="ut-status-label">Metode Ekstraksi:</span>
            <span style="font-family: monospace; font-weight: 700; color: #0284c7; letter-spacing: 2px;" title="Metode dilindungi (Secret)">*****</span>
          </div>
          <div class="ut-status-row">
            <span class="ut-status-label">Terkumpul:</span>
            <span class="ut-count-value" id="ut-page-count">0 Bagian</span>
          </div>
          <div class="ut-status-row">
            <span class="ut-status-label">Bab Aktif:</span>
            <span class="ut-current-title" id="ut-current-section">-</span>
          </div>
        </div>

        <div class="ut-form-group">
          <label for="ut-doc-label" class="ut-form-label">
            <span>🏷️ Nama Label / Judul File:</span>
          </label>
          <div class="ut-input-wrapper">
            <input type="text" id="ut-doc-label" class="ut-text-input" placeholder="Contoh: Modul 1 - Matriks" value="" autocomplete="off" spellcheck="false" style="padding-left: 14px !important; padding-right: 14px !important; text-indent: 0 !important;">
          </div>
        </div>

        <div class="ut-form-group">
          <label for="ut-max-pages" class="ut-form-label">
            <span>🎯 Batas Halaman (Auto-Stop):</span>
          </label>
          <div class="ut-select-wrapper">
            <select id="ut-max-pages" class="ut-select">
              <option value="5">Maksimal 5 Halaman</option>
              <option value="10">Maksimal 10 Halaman</option>
              <option value="15" selected>Maksimal 15 Halaman (Direkomendasikan)</option>
              <option value="25">Maksimal 25 Halaman</option>
              <option value="50">Maksimal 50 Halaman</option>
              <option value="0">Semua Halaman (Tanpa Batas)</option>
              <option value="custom">✏️ Kustom / Tentukan Manual...</option>
            </select>
            <input type="number" id="ut-max-pages-custom" class="ut-text-input ut-hidden" min="1" max="1000" placeholder="Ketik jumlah halaman (misal: 12)" style="margin-top: 6px; display: none; padding-left: 14px !important; padding-right: 14px !important;">
          </div>
        </div>

        <div class="ut-form-group">
          <div class="ut-form-label-row">
            <span class="ut-form-label" style="margin-bottom: 0;">⏱️ Kecepatan Jeda (Delay):</span>
            <span id="ut-delay-val" class="ut-badge-delay">2.5s</span>
          </div>
          <input type="range" id="ut-delay-slider" class="ut-slider-input" min="1.0" max="6.0" step="0.5" value="2.5">
        </div>

        <div class="ut-actions-grid">
          <button class="ut-btn ut-btn-success ut-btn-full" id="ut-btn-start">
            ▶️ Mulai Auto-Scan
          </button>
          <button class="ut-btn ut-btn-danger" id="ut-btn-stop" style="display: none;">
            ⏹️ Stop Scan
          </button>
          <button class="ut-btn ut-btn-secondary" id="ut-btn-capture">
            📸 Scan Halaman Ini
          </button>
          <button class="ut-btn ut-btn-secondary" id="ut-btn-clear" title="Hapus data terkumpul">
            🗑️ Reset
          </button>
        </div>

        <div class="ut-export-section">
          <div class="ut-export-label">Ekspor Dokumen (Landscape HD)</div>
          <div class="ut-export-btns">
            <button class="ut-btn ut-btn-primary" id="ut-btn-export-doc">
              📄 Word (.docx)
            </button>
            <button class="ut-btn ut-btn-secondary" id="ut-btn-export-pdf">
              📑 Cetak / PDF
            </button>
          </div>
        </div>
      </div>
    `;

    document.body.appendChild(widget);
    attachWidgetListeners(widget);
    makeDraggable(widget, document.getElementById('ut-widget-drag-handle'));
    unblockProtection();
  }

  // Attach button and slider event listeners
  function attachWidgetListeners(widget) {
    const btnStart = widget.querySelector('#ut-btn-start');
    const btnStop = widget.querySelector('#ut-btn-stop');
    const btnCapture = widget.querySelector('#ut-btn-capture');
    const btnClear = widget.querySelector('#ut-btn-clear');
    const btnExportDoc = widget.querySelector('#ut-btn-export-doc');
    const btnExportPdf = widget.querySelector('#ut-btn-export-pdf');
    const btnMin = widget.querySelector('#ut-btn-minimize');
    const delaySlider = widget.querySelector('#ut-delay-slider');
    const delayVal = widget.querySelector('#ut-delay-val');
    const maxPagesSelect = widget.querySelector('#ut-max-pages');
    const maxPagesCustom = widget.querySelector('#ut-max-pages-custom');
    const docLabelInput = widget.querySelector('#ut-doc-label');

    // Default placeholder label if book title is known
    if (state.bookTitle && !state.customLabel) {
      docLabelInput.value = state.bookTitle;
    }

    docLabelInput.addEventListener('input', (e) => {
      state.customLabel = e.target.value;
    });

    delaySlider.addEventListener('input', (e) => {
      state.delaySeconds = parseFloat(e.target.value);
      delayVal.textContent = `${state.delaySeconds.toFixed(1)}s`;
    });

    maxPagesSelect.addEventListener('change', (e) => {
      if (e.target.value === 'custom') {
        maxPagesCustom.classList.remove('ut-hidden');
        maxPagesCustom.focus();
        const customVal = parseInt(maxPagesCustom.value, 10);
        state.maxPages = (customVal > 0) ? customVal : 15;
      } else {
        maxPagesCustom.classList.add('ut-hidden');
        state.maxPages = parseInt(e.target.value, 10);
      }
    });

    maxPagesCustom.addEventListener('input', (e) => {
      const customVal = parseInt(e.target.value, 10);
      if (!isNaN(customVal) && customVal > 0) {
        state.maxPages = customVal;
      }
    });

    btnMin.addEventListener('click', (e) => {
      e.stopPropagation();
      widget.classList.toggle('minimized');
      btnMin.textContent = widget.classList.contains('minimized') ? '⤢' : '−';
    });

    btnStart.addEventListener('click', () => {
      if (maxPagesSelect.value === 'custom') {
        const customVal = parseInt(maxPagesCustom.value, 10);
        state.maxPages = (customVal > 0) ? customVal : 15;
      } else {
        state.maxPages = parseInt(maxPagesSelect.value, 10);
      }
      state.customLabel = docLabelInput.value;
      startScanning();
    });

    btnStop.addEventListener('click', () => {
      stopScanning('Scan dihentikan oleh pengguna.');
    });

    btnCapture.addEventListener('click', async () => {
      state.customLabel = docLabelInput.value;
      showToast('📸 Mengambil tangkapan halaman...');
      const extracted = await extractCurrentContent();
      if (extracted && (extracted.image || (extracted.text && extracted.text.length > 5))) {
        addPageIfNew(extracted);
        showToast(`✅ Tersimpan: ${extracted.title || 'Halaman saat ini'}`);
      } else {
        showToast('⚠️ Gagal mengambil screenshot.', 3000);
      }
    });

    btnClear.addEventListener('click', () => {
      if (confirm('Apakah Anda yakin ingin menghapus data materi yang sudah terkumpul?')) {
        state.pages = [];
        state.lastContentHash = '';
        saveState();
        updateWidgetUI();
        showToast('🗑️ Data materi berhasil direset.');
      }
    });

    btnExportDoc.addEventListener('click', async () => {
      if (state.pages.length === 0) {
        showToast('⚠️ Belum ada materi yang discan!');
        return;
      }
      state.customLabel = docLabelInput.value;
      showToast('📄 Sedang menyusun dokumen Word (.docx Landscape)...');
      try {
        const payload = getBookPayload();
        const blob = await BookExporter.toDocxBlob(payload);
        const rawTitle = state.customLabel.trim() || state.bookTitle || 'Modul_UT';
        const safeTitle = rawTitle.replace(/[^a-zA-Z0-9_\-\s]/g, '').trim().replace(/\s+/g, '_');
        BookExporter.downloadFile(blob, `${safeTitle}.docx`);
        showToast(`✅ Berhasil mengunduh: ${safeTitle}.docx`);
      } catch (err) {
        console.error('Docx export error:', err);
        showToast('Gagal generate docx, periksa konsol browser.');
      }
    });

    btnExportPdf.addEventListener('click', () => {
      if (state.pages.length === 0) {
        showToast('⚠️ Belum ada materi yang discan!');
        return;
      }
      state.customLabel = docLabelInput.value;
      showToast('📑 Membuka jendela cetak / simpan PDF...');
      BookExporter.openPrintablePDF(getBookPayload());
    });
  }

  // Make floating widget draggable with pointer capture & iframe protection
  function makeDraggable(element, handle) {
    let isDragging = false;
    let startX = 0, startY = 0;
    let initialLeft = 0, initialTop = 0;

    try {
      const savedPos = localStorage.getItem('ut_scanner_widget_pos');
      if (savedPos) {
        const { left, top } = JSON.parse(savedPos);
        const maxLeft = Math.max(10, window.innerWidth - 340);
        const maxTop = Math.max(10, window.innerHeight - 100);
        const clampedLeft = Math.min(Math.max(10, left), maxLeft);
        const clampedTop = Math.min(Math.max(10, top), maxTop);
        
        element.style.left = `${clampedLeft}px`;
        element.style.top = `${clampedTop}px`;
        element.style.bottom = 'auto';
        element.style.right = 'auto';
      }
    } catch (e) {}

    let hasMoved = false;

    handle.addEventListener('pointerdown', (e) => {
      if (e.target.tagName === 'BUTTON' || e.target.closest('button')) return;

      isDragging = true;
      hasMoved = false;
      handle.setPointerCapture(e.pointerId);
      document.body.classList.add('ut-dragging');

      const rect = element.getBoundingClientRect();
      startX = e.clientX;
      startY = e.clientY;
      initialLeft = rect.left;
      initialTop = rect.top;

      element.style.bottom = 'auto';
      element.style.right = 'auto';
      element.style.left = `${initialLeft}px`;
      element.style.top = `${initialTop}px`;
    });

    handle.addEventListener('pointermove', (e) => {
      if (!isDragging) return;

      const deltaX = e.clientX - startX;
      const deltaY = e.clientY - startY;

      if (Math.abs(deltaX) > 4 || Math.abs(deltaY) > 4) {
        hasMoved = true;
      }

      let newLeft = initialLeft + deltaX;
      let newTop = initialTop + deltaY;

      const maxLeft = window.innerWidth - element.offsetWidth - 10;
      const maxTop = window.innerHeight - element.offsetHeight - 10;

      newLeft = Math.max(10, Math.min(newLeft, maxLeft));
      newTop = Math.max(10, Math.min(newTop, maxTop));

      element.style.left = `${newLeft}px`;
      element.style.top = `${newTop}px`;
    });

    const endDrag = (e) => {
      if (!isDragging) return;
      isDragging = false;
      document.body.classList.remove('ut-dragging');
      try {
        handle.releasePointerCapture(e.pointerId);
      } catch (err) {}

      // If clicked while minimized and didn't drag, expand widget!
      if (!hasMoved && element.classList.contains('minimized')) {
        element.classList.remove('minimized');
        const btnMin = element.querySelector('#ut-btn-minimize');
        if (btnMin) btnMin.textContent = '−';
      }

      const rect = element.getBoundingClientRect();
      try {
        localStorage.setItem('ut_scanner_widget_pos', JSON.stringify({
          left: Math.round(rect.left),
          top: Math.round(rect.top)
        }));
      } catch (err) {}
    };

    handle.addEventListener('pointerup', endDrag);
    handle.addEventListener('pointercancel', endDrag);
  }

  function showToast(message, duration = 3000) {
    const existing = document.querySelector('.ut-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = 'ut-toast';
    toast.innerHTML = `<span>${message}</span>`;
    document.body.appendChild(toast);

    setTimeout(() => {
      toast.style.opacity = '0';
      setTimeout(() => toast.remove(), 300);
    }, duration);
  }

  function updateWidgetUI() {
    const widget = document.getElementById('ut-scanner-widget');
    if (!widget) return;

    const badgeStatus = widget.querySelector('#ut-badge-status');
    const pageCount = widget.querySelector('#ut-page-count');
    const currentSection = widget.querySelector('#ut-current-section');
    const btnStart = widget.querySelector('#ut-btn-start');
    const btnStop = widget.querySelector('#ut-btn-stop');

    pageCount.textContent = `${state.pages.length} Bagian`;

    if (state.pages.length > 0) {
      const last = state.pages[state.pages.length - 1];
      currentSection.textContent = last.title || `Halaman ${state.pages.length}`;
    } else {
      currentSection.textContent = '-';
    }

    if (state.isScanning) {
      badgeStatus.textContent = 'SCANNING...';
      badgeStatus.className = 'ut-status-badge scanning';
      btnStart.style.display = 'none';
      btnStop.style.display = 'flex';
      btnStop.textContent = '⏹️ Stop Scan';
    } else {
      badgeStatus.textContent = 'IDLE';
      badgeStatus.className = 'ut-status-badge idle';
      btnStart.style.display = 'flex';
      btnStop.style.display = 'none';
    }
  }

  // Lightweight state notification (does NOT serialize large images to prevent lagging!)
  function saveState() {
    chrome.runtime.sendMessage({
      action: 'STATE_UPDATED',
      count: state.pages.length,
      isScanning: state.isScanning,
      bookTitle: state.bookTitle
    }).catch(() => {});
  }

  function getBookPayload() {
    return {
      title: state.customLabel.trim() || state.bookTitle || getBookTitleFromPage() || 'Modul Universitas Terbuka',
      url: window.location.href,
      scanDate: new Date().toLocaleString('id-ID'),
      pages: state.pages
    };
  }

  function computeHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash |= 0;
    }
    return String(hash);
  }

  function getBookTitleFromPage() {
    const headerTitle = document.querySelector('.header-title, .book-title, [class*="header"] [class*="title"]');
    if (headerTitle && headerTitle.innerText.trim()) {
      return headerTitle.innerText.trim();
    }

    const topH1 = document.querySelector('h1');
    if (topH1 && topH1.innerText.trim()) {
      return topH1.innerText.trim();
    }

    const sidebarTitle = document.querySelector('.sidebar [class*="title"], .nav-title, .cover-title');
    if (sidebarTitle && sidebarTitle.innerText.trim()) {
      return sidebarTitle.innerText.trim();
    }

    return document.title.replace(/Kotobee|Reader/gi, '').trim() || 'Modul Universitas Terbuka';
  }

  function generateCanvasSnapshotFromDOM(title, text) {
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 1200;
      canvas.height = 700;
      const ctx = canvas.getContext('2d');

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#0284c7';
      ctx.font = 'bold 26px Calibri, Arial, sans-serif';
      ctx.fillText(title || 'Halaman Modul', 60, 60);

      ctx.strokeStyle = '#e2e8f0';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(60, 80);
      ctx.lineTo(1140, 80);
      ctx.stroke();

      ctx.fillStyle = '#1e293b';
      ctx.font = '16px Calibri, Arial, sans-serif';
      
      const paragraphs = (text || 'Tangkapan halaman modul UT.').split('\n');
      let y = 120;
      for (const p of paragraphs) {
        if (!p.trim()) {
          y += 10;
          continue;
        }
        const words = p.split(' ');
        let currentLine = '';
        for (const word of words) {
          const testLine = currentLine + word + ' ';
          if (ctx.measureText(testLine).width > 1080 && currentLine.length > 0) {
            ctx.fillText(currentLine, 60, y);
            currentLine = word + ' ';
            y += 24;
            if (y > 660) break;
          } else {
            currentLine = testLine;
          }
        }
        ctx.fillText(currentLine, 60, y);
        y += 28;
        if (y > 660) break;
      }

      return canvas.toDataURL('image/jpeg', 0.80);
    } catch (e) {
      return null;
    }
  }

  // Capture Screenshot of Book Reader with clean hiding & lightweight compression
  async function captureReaderScreenshot(fallbackTitle = '', fallbackText = '') {
    const widget = document.getElementById('ut-scanner-widget');
    try {
      if (widget) {
        widget.style.display = 'none';
      }
      await new Promise(r => setTimeout(r, 120));

      const response = await chrome.runtime.sendMessage({ action: 'CAPTURE_TAB_SCREEN' });
      
      if (widget) {
        widget.style.display = 'block';
      }

      if (response && response.success && response.dataUrl) {
        const cropped = await cropScreenshot(response.dataUrl);
        return cropped;
      }
    } catch (e) {
      console.warn('Screenshot capture notice:', e);
    } finally {
      if (widget) {
        widget.style.display = 'block';
      }
    }

    const fallbackUrl = generateCanvasSnapshotFromDOM(fallbackTitle, fallbackText);
    return { dataUrl: fallbackUrl, width: 1200, height: 700 };
  }

  // Crop screenshot to reader area precisely
  function cropScreenshot(dataUrl) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => {
        try {
          const scale = img.width / window.innerWidth;

          // Find sidebar precisely
          const sidebar = document.querySelector('.sidebar, [class*="sidebar"], [class*="toc-container"], [class*="side-nav"]');
          let sidebarRight = 0;
          if (sidebar && sidebar.offsetWidth > 40 && sidebar.offsetWidth < 500) {
            const sRect = sidebar.getBoundingClientRect();
            sidebarRight = sRect.right;
          }

          const topBar = document.querySelector('header, .header, [class*="header"], [class*="top-bar"], .app-header');
          const topBottom = (topBar && topBar.offsetHeight > 20 && topBar.offsetHeight < 140) ? topBar.getBoundingClientRect().bottom : 50;

          const bottomBar = document.querySelector('footer, .footer, [class*="footer"], [class*="bottom-nav"], .app-footer');
          const bottomTop = (bottomBar && bottomBar.offsetHeight > 20 && bottomBar.offsetHeight < 140) ? bottomBar.getBoundingClientRect().top : (window.innerHeight - 55);

          const cropX = Math.max(0, sidebarRight * scale);
          const cropY = Math.max(0, topBottom * scale);
          const cropW = Math.min(img.width - cropX, (window.innerWidth - sidebarRight) * scale);
          const cropH = Math.min(img.height - cropY, (bottomTop - topBottom) * scale);

          const canvas = document.createElement('canvas');
          const ctx = canvas.getContext('2d');

          canvas.width = Math.max(300, Math.round(cropW));
          canvas.height = Math.max(200, Math.round(cropH));

          ctx.drawImage(img, cropX, cropY, cropW, cropH, 0, 0, canvas.width, canvas.height);
          
          // Balanced lightweight JPEG (quality 0.80) to prevent memory lag
          resolve({
            dataUrl: canvas.toDataURL('image/jpeg', 0.80),
            width: canvas.width,
            height: canvas.height
          });
        } catch (e) {
          resolve({ dataUrl, width: img.width, height: img.height });
        }
      };
      img.onerror = () => resolve({ dataUrl, width: 1600, height: 900 });
      img.src = dataUrl;
    });
  }

  function getCurrentPageTitle(contentDoc) {
    const headerEl = document.querySelector('.header, header, [class*="header"], [class*="navbar"], [class*="topbar"], .app-header');
    if (headerEl) {
      const items = Array.from(headerEl.querySelectorAll('span, div, h1, h2, h3, p'));
      for (const el of items) {
        const txt = el.innerText?.trim();
        if (txt && (/^(Halaman|Modul|Tinjauan|Bab|Kegiatan)/i.test(txt) || (txt.length < 50 && txt.includes('.')))) {
          if (!txt.includes('Library') && !txt.includes('Menu')) {
            return txt;
          }
        }
      }
    }

    const activeToc = document.querySelector('.toc-item.active, .chapter-list li.active, [class*="active"][class*="item"], [class*="active"]');
    if (activeToc && activeToc.innerText.trim().length > 0 && activeToc.innerText.trim().length < 60) {
      const t = activeToc.innerText.trim();
      if (!t.includes('Table of Contents')) return t;
    }

    if (contentDoc) {
      const h = contentDoc.querySelector('h1, h2, .chapter-title, .title');
      if (h && h.innerText?.trim()) {
        return h.innerText.trim();
      }
    }

    return `Halaman ${state.pages.length + 1}`;
  }

  function generateContentSignature(title, image) {
    if (!image) return computeHash(title || '');
    const len = image.length;
    const s1 = image.slice(100, 300);
    const s2 = image.slice(Math.floor(len * 0.25), Math.floor(len * 0.25) + 200);
    const s3 = image.slice(Math.floor(len * 0.50), Math.floor(len * 0.50) + 200);
    const s4 = image.slice(Math.floor(len * 0.75), Math.floor(len * 0.75) + 200);
    const s5 = image.slice(-250, -50);
    return computeHash(`${title || ''}_${len}_${s1}_${s2}_${s3}_${s4}_${s5}`);
  }

  async function extractCurrentContent() {
    unblockProtection();

    let contentDoc = document;
    let image = null;
    let imageWidth = 1600;
    let imageHeight = 900;

    if (!state.bookTitle) {
      state.bookTitle = getBookTitleFromPage();
    }

    const iframes = Array.from(document.querySelectorAll('iframe'));
    for (const iframe of iframes) {
      try {
        const doc = iframe.contentDocument || iframe.contentWindow?.document;
        if (doc && doc.body && doc.body.innerText.trim().length > 10) {
          contentDoc = doc;
          break;
        }
      } catch (e) {}
    }

    const title = getCurrentPageTitle(contentDoc);
    const shotResult = await captureReaderScreenshot(title, '');
    
    if (shotResult) {
      if (typeof shotResult === 'string') {
        image = shotResult;
      } else {
        image = shotResult.dataUrl;
        imageWidth = shotResult.width;
        imageHeight = shotResult.height;
      }
    }

    const sig = generateContentSignature(title, image);

    return {
      title: title || `Halaman ${state.pages.length + 1}`,
      image: image,
      width: imageWidth,
      height: imageHeight,
      timestamp: new Date().toISOString(),
      hash: sig
    };
  }

  function addPageIfNew(extracted) {
    if (!extracted || !extracted.image) {
      return false;
    }

    if (state.pages.length > 0) {
      const lastPage = state.pages[state.pages.length - 1];
      if (extracted.hash && lastPage.hash === extracted.hash) {
        return false;
      }
    }

    state.pages.push(extracted);
    state.lastContentHash = extracted.hash;
    saveState();
    updateWidgetUI();
    return true;
  }

  function simulateDirectClick(el) {
    if (!el) return;
    try {
      const rect = el.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;

      const eventOpts = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy };
      el.dispatchEvent(new PointerEvent('pointerdown', eventOpts));
      el.dispatchEvent(new MouseEvent('mousedown', eventOpts));
      el.dispatchEvent(new PointerEvent('pointerup', eventOpts));
      el.dispatchEvent(new MouseEvent('mouseup', eventOpts));
      el.click();
    } catch (e) {
      try { el.click(); } catch (err) {}
    }
  }

  function clickNextButton() {
    // 1. Direct search for Kotobee Next elements
    const candidates = [
      ...Array.from(document.querySelectorAll('button, a, div, span, [role="button"], footer *'))
    ];

    for (const el of candidates) {
      const text = (el.innerText || '').trim().toLowerCase();
      const title = (el.getAttribute('title') || '').toLowerCase();
      const aria = (el.getAttribute('aria-label') || '').toLowerCase();
      const id = (el.id || '').toLowerCase();
      const cls = (typeof el.className === 'string' ? el.className : '').toLowerCase();

      if (text.includes('prev') || title.includes('prev') || cls.includes('prev') || aria.includes('prev')) continue;

      if (
        (text === 'next' || text === 'next >' || text === 'next>' || text === '>' || text === 'selanjutnya') ||
        (title === 'next' || title === 'next page' || title === 'halaman selanjutnya') ||
        (aria === 'next' || aria === 'next page' || aria === 'halaman selanjutnya') ||
        (id === 'next' || id === 'next-btn' || id === 'btn-next' || id === 'btnnext' || id === 'btn_next') ||
        (cls.includes('next-button') || cls.includes('btn-next') || cls.includes('page-next') || cls.includes('nav-next') || cls.includes('arrow-next') || cls.includes('chevron-next'))
      ) {
        if (el.offsetParent !== null && !el.disabled) {
          simulateDirectClick(el);
          triggerKeyboardNext();
          return true;
        }
      }
    }

    // 2. Footer right side navigation icons/buttons
    const bottomNavIcons = document.querySelectorAll('footer [class*="right"], [class*="footer"] [class*="next"], [class*="nav"] [class*="next"], [class*="arrow-right"], [class*="chevron-right"], [class*="arrow_right"], [class*="chevron_right"]');
    for (const icon of bottomNavIcons) {
      const clickable = icon.closest('button, a, div[role="button"]') || icon;
      if (clickable && clickable.offsetParent !== null) {
        simulateDirectClick(clickable);
        triggerKeyboardNext();
        return true;
      }
    }

    // 3. Fallback: Keyboard arrow events
    triggerKeyboardNext();
    return true;
  }

  function triggerKeyboardNext() {
    const keyEventOptions = {
      key: 'ArrowRight',
      code: 'ArrowRight',
      keyCode: 39,
      which: 39,
      bubbles: true,
      cancelable: true
    };

    window.dispatchEvent(new KeyboardEvent('keydown', keyEventOptions));
    window.dispatchEvent(new KeyboardEvent('keyup', keyEventOptions));
    document.dispatchEvent(new KeyboardEvent('keydown', keyEventOptions));
    document.dispatchEvent(new KeyboardEvent('keyup', keyEventOptions));

    document.querySelectorAll('iframe').forEach(iframe => {
      try {
        const win = iframe.contentWindow;
        const doc = iframe.contentDocument || win?.document;
        if (win && doc) {
          win.dispatchEvent(new KeyboardEvent('keydown', keyEventOptions));
          win.dispatchEvent(new KeyboardEvent('keyup', keyEventOptions));
          doc.dispatchEvent(new KeyboardEvent('keydown', keyEventOptions));
          doc.dispatchEvent(new KeyboardEvent('keyup', keyEventOptions));
        }
      } catch (e) {}
    });
  }

  async function startScanning() {
    if (state.isScanning) return;
    state.isScanning = true;
    state.consecutiveSameCount = 0;
    updateWidgetUI();
    showToast(`🚀 Auto-Scan dimulai (Batas: ${state.maxPages > 0 ? state.maxPages + ' Halaman' : 'Tanpa Batas'})`);

    await runScanStep();
  }

  async function runScanStep() {
    if (!state.isScanning) return;

    // Check page limit
    if (state.maxPages > 0 && state.pages.length >= state.maxPages) {
      stopScanning(`🏁 Selesai: Telah mencapai target batas ${state.maxPages} halaman!`);
      return;
    }

    const current = await extractCurrentContent();
    const isNew = addPageIfNew(current);

    if (state.maxPages > 0 && state.pages.length >= state.maxPages) {
      stopScanning(`🏁 Selesai: Telah mencapai target batas ${state.maxPages} halaman!`);
      return;
    }

    if (!isNew) {
      state.consecutiveSameCount++;
    } else {
      state.consecutiveSameCount = 0;
    }

    // Allow more resilience (up to 8 consecutive retries before concluding end of book)
    if (state.consecutiveSameCount >= 8) {
      stopScanning('🏁 Auto-Scan selesai: Sudah mencapai halaman terakhir buku.');
      return;
    }

    clickNextButton();

    const delayMs = Math.max(1500, state.delaySeconds * 1000);
    state.timerId = setTimeout(async () => {
      await runScanStep();
    }, delayMs);
  }

  function stopScanning(reason = 'Scan dihentikan.') {
    state.isScanning = false;
    if (state.timerId) {
      clearTimeout(state.timerId);
      state.timerId = null;
    }
    updateWidgetUI();
    saveState();
    showToast(reason);
  }

  // Listen for messages from Popup
  chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
    (async () => {
      if (request.action === 'GET_STATUS') {
        sendResponse({
          isScanning: state.isScanning,
          pageCount: state.pages.length,
          bookTitle: state.bookTitle,
          customLabel: state.customLabel || '',
          pages: state.pages,
          delaySeconds: state.delaySeconds,
          maxPages: state.maxPages
        });
        return;
      }

      if (request.action === 'SET_LABEL') {
        state.customLabel = request.label || '';
        const docLabelInput = document.querySelector('#ut-doc-label');
        if (docLabelInput) docLabelInput.value = state.customLabel;
        sendResponse({ success: true });
        return;
      }

      if (request.action === 'START_SCAN') {
        if (request.delay) state.delaySeconds = request.delay;
        if (typeof request.maxPages === 'number') state.maxPages = request.maxPages;
        if (typeof request.customLabel === 'string') {
          state.customLabel = request.customLabel;
          const docLabelInput = document.querySelector('#ut-doc-label');
          if (docLabelInput) docLabelInput.value = state.customLabel;
        }
        await startScanning();
        sendResponse({ success: true });
        return;
      }

      if (request.action === 'STOP_SCAN') {
        stopScanning('Scan dihentikan dari popup.');
        sendResponse({ success: true });
        return;
      }

      if (request.action === 'CLEAR_DATA') {
        state.pages = [];
        state.lastContentHash = '';
        saveState();
        updateWidgetUI();
        sendResponse({ success: true });
        return;
      }

      if (request.action === 'CAPTURE_NOW') {
        const extracted = await extractCurrentContent();
        if (extracted && extracted.image) {
          addPageIfNew(extracted);
          sendResponse({ success: true, page: extracted });
        } else {
          sendResponse({ success: false, message: 'Screenshot gagal' });
        }
        return;
      }
    })();
    return true;
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', injectWidget);
  } else {
    injectWidget();
  }

  setInterval(unblockProtection, 2000);

})();
